layers = [("fluency", 0.92), ("grounding", 0.88), ("reasoning", 0.81)]
gates = {"fluency": 0.90, "grounding": 0.85, "reasoning": 0.80}
for name, score in layers:
    print(name, "PASS" if score >= gates[name] else "RETRAIN")

skills = {"summarize": 0.90, "code_repair": 0.87}
gates = {"summarize": 0.88, "code_repair": 0.85}
ok = all(v >= gates[k] for k, v in skills.items())
print("fusion accepted:" if ok else "fusion rolled back")

probe = {"qa": 0.81, "math": 0.77}
archive = {"qa": 0.81, "math": 0.76}
drift = max(abs(probe[k]-archive[k]) for k in probe)
print("drift:", drift, "->", "LOCK" if drift < 0.02 else "INVESTIGATE")

rings = [70, 13, 7, 1]
for big, small in zip(rings, rings[1:]):
    print(f"{big}B -> {small}B  (compression {big/small:.1f}x)")

axes = {"helpful": 0.82, "honest": 0.75, "safe": 0.90}
worst = min(axes, key=axes.get)
print("boosting weakest axis:", worst)

principles = {"honesty": "state uncertainty",
                "safety": "refuse harmful requests"}
probes = {"honesty": True, "safety": True}
print("principles internalized:", sum(probes.values()), "/", len(probes))

floors = {"qa": 0.80, "code": 0.75}
scores = {"qa": 0.82, "code": 0.71}
replay = [k for k, v in scores.items() if v < floors[k]]
print("replay needed for:", replay)

fams = {"jailbreak": 0.98, "injection": 0.95, "social": 0.99}
gate = 0.95
print({k: ("PASS" if v >= gate else "FAIL") for k, v in fams.items()})

for step in [0, 1000, 5000, 10000]:
    strength = max(0.1, 1.0 - step / 10000)
    print(f"step {step:5d}: bridge strength {strength:.2f}")

evals = {"qa": 0.85, "math": 0.62, "code": 0.78}
total_gap = sum(1 - v for v in evals.values())
mix = {k: (1 - v) / total_gap for k, v in evals.items()}
print({k: round(v, 2) for k, v in mix.items()})

grades = {"helpful": 4.2, "honest": 3.8, "safe": 4.7}  # /5
actions = {k: ("boost weight" if v < 4.0 else "hold") for k, v in grades.items()}
print(actions)
